#nullable enable // autogenerated

using System;
using MVZ2.UI;
using TMPro;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace MVZ2.Level.Curses
{
    public class CursePanelEntranceButton : MonoBehaviour, ITooltipTarget, IPointerEnterHandler, IPointerExitHandler
    {
        public void SetText(string text)
        {
            this.text.text = text;
        }
        public void SetInteractable(bool interactable)
        {
            button.interactable = interactable;
        }
        private void Awake()
        {
            button.onClick.AddListener(() => OnClick?.Invoke());
        }
        void IPointerEnterHandler.OnPointerEnter(PointerEventData eventData)
        {
            OnPointerEnter?.Invoke();
        }
        void IPointerExitHandler.OnPointerExit(PointerEventData eventData)
        {
            OnPointerExit?.Invoke();
        }
        public event Action? OnClick;
        public event Action? OnPointerEnter;
        public event Action? OnPointerExit;
        [SerializeField]
        private TextMeshProUGUI text = null!;
        [SerializeField]
        private Button button = null!;
        [SerializeField]
        private TooltipAnchor tooltipAnchor = null!;

        ITooltipAnchor ITooltipTarget.Anchor => tooltipAnchor;
    }
}
